SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS `st_meta`;
CREATE TABLE IF NOT EXISTS `st_meta`.`targets` (db VARCHAR(64) NOT NULL, tbl VARCHAR(64) NOT NULL, captured TINYINT NOT NULL, native TINYINT NOT NULL, family VARCHAR(16) NOT NULL, PRIMARY KEY (db, tbl)) DEFAULT CHARACTER SET utf8mb4;
DROP DATABASE IF EXISTS `st_part`;
CREATE DATABASE `st_part` DEFAULT CHARACTER SET utf8mb4;
DROP DATABASE IF EXISTS `st_dropdb`;
CREATE DATABASE `st_dropdb` DEFAULT CHARACTER SET utf8mb4;
DROP DATABASE IF EXISTS `st_dropother`;
CREATE DATABASE `st_dropother` DEFAULT CHARACTER SET utf8mb4;
DELETE FROM `st_meta`.`targets` WHERE db IN ('st_part', 'st_dropdb', 'st_dropother');
CREATE TABLE `st_part`.`kinds` (`id` INT NOT NULL PRIMARY KEY, `amount` INT NOT NULL, `note` VARCHAR(40)) ENGINE=InnoDB PARTITION BY RANGE (`id`) (PARTITION p0 VALUES LESS THAN (3), PARTITION p1 VALUES LESS THAN (6), PARTITION p2 VALUES LESS THAN MAXVALUE);
INSERT INTO `st_part`.`kinds` SELECT n, n * 10, CONCAT('part ', n) FROM (WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 5) SELECT n FROM s) q;
INSERT INTO `st_meta`.`targets` VALUES ('st_part', 'kinds', 1, 0, 'part');
CREATE TABLE `st_part`.`plain` (`id` INT NOT NULL PRIMARY KEY, `amount` INT NOT NULL, `note` VARCHAR(40)) ENGINE=InnoDB;
INSERT INTO `st_part`.`plain` SELECT n, n * 10, CONCAT('plain ', n) FROM (WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 2) SELECT n FROM s) q;
INSERT INTO `st_meta`.`targets` VALUES ('st_part', 'plain', 1, 0, 'part');
CREATE TABLE `st_part`.`swap` (`id` INT NOT NULL PRIMARY KEY, `amount` INT NOT NULL, `note` VARCHAR(40)) ENGINE=InnoDB;
INSERT INTO `st_part`.`swap` SELECT n, n * 10, CONCAT('swap ', n) FROM (WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 2) SELECT n FROM s) q;
INSERT INTO `st_meta`.`targets` VALUES ('st_part', 'swap', 0, 0, 'part');
CREATE TABLE `st_part`.`other` (`id` INT NOT NULL PRIMARY KEY, `amount` INT NOT NULL, `note` VARCHAR(40)) ENGINE=InnoDB PARTITION BY RANGE (`id`) (PARTITION p0 VALUES LESS THAN (3), PARTITION p1 VALUES LESS THAN (6), PARTITION p2 VALUES LESS THAN MAXVALUE);
INSERT INTO `st_part`.`other` SELECT n, n * 10, CONCAT('other ', n) FROM (WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 5) SELECT n FROM s) q;
INSERT INTO `st_meta`.`targets` VALUES ('st_part', 'other', 0, 0, 'part');
CREATE TABLE `st_dropdb`.`kinds` (`id` INT NOT NULL PRIMARY KEY, `amount` INT NOT NULL, `note` VARCHAR(40)) ENGINE=InnoDB;
INSERT INTO `st_dropdb`.`kinds` SELECT n, n * 10, CONCAT('drop ', n) FROM (WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 5) SELECT n FROM s) q;
INSERT INTO `st_meta`.`targets` VALUES ('st_dropdb', 'kinds', 1, 0, 'part');
CREATE TABLE `st_dropdb`.`tmp` (`id` INT NOT NULL PRIMARY KEY, `amount` INT NOT NULL, `note` VARCHAR(40)) ENGINE=InnoDB;
INSERT INTO `st_dropdb`.`tmp` SELECT n, n * 10, CONCAT('drop ', n) FROM (WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 5) SELECT n FROM s) q;
INSERT INTO `st_meta`.`targets` VALUES ('st_dropdb', 'tmp', 0, 0, 'part');
CREATE TABLE `st_dropother`.`tmp` (`id` INT NOT NULL PRIMARY KEY, `amount` INT NOT NULL, `note` VARCHAR(40)) ENGINE=InnoDB;
INSERT INTO `st_dropother`.`tmp` SELECT n, n * 10, CONCAT('drop ', n) FROM (WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 5) SELECT n FROM s) q;
INSERT INTO `st_meta`.`targets` VALUES ('st_dropother', 'tmp', 0, 0, 'part');
